{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    # Build list of mutual reachability edges
    edges = []
    for u, v, d in case['distances']:
        left, right = (u, v) if u < v else (v, u)
        weight = max(core[u], core[v], d)
        edges.append((weight, left, right))
    # Sort by weight, then by left, then by right (lexicographic)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    needed = len(nodes) - 1
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == needed:
                break
    # Ensure graph is connected – if not enough edges, raise but for this task assume valid
    if len(mst_edges) != needed:
        raise ValueError('Disconnected graph')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"}
